1	//! vLLM-compatible block-hash derivation for cross-engine P/D KV lookup.
2	//!
3	//! When vLLM is the prefill node, its pegaflow connector registers KV blocks
4	//! under vLLM's own prefix-cache hashes (`vllm/v1/core/kv_cache_utils.py::
5	//! hash_block_tokens`). For an pegainfer decode node to find those blocks by
6	//! content, it must derive byte-identical keys from the same token sequence.
7	//! This module mirrors exactly one vLLM configuration — the only one that is
8	//! replicable outside Python:
9	//!
10	//! - `--prefix-caching-hash-algo xxhash_cbor`: key = `xxh3_128(cbor(input))`
11	//!   with canonical CBOR (RFC 8949). The non-`_cbor` variants serialize via
12	//!   pickle and cannot be reproduced here.
13	//! - `PYTHONHASHSEED` set on every vLLM process: the chain root `NONE_HASH` is
14	//!   `xxh3_128(cbor(seed_string))`. Unset, vLLM falls back to `os.urandom` and
15	//!   keys are unreproducible across processes — deployment must fail fast.
16	//! - Text-only requests: vLLM's `extra_keys` (multimodal, LoRA, cache salt)
17	//!   are `None`. Anything else diverges and must be caught by the compat gate.
18	//!
19	//! Per block the hashed input is the 3-tuple `(parent_hash: bytes,
20	//! token_ids: tuple[int, ...], None)`, encoded as a CBOR array. vLLM only
21	//! hashes full blocks; the partial tail block has no vLLM hash. The P/D tail
22	//! extension applies the same function to the partial token list, which both
23	//! sides can derive (`docs/models/glm52/pd-vllm-prefill.md` §3).
24	
25	use xxhash_rust::xxh3::xxh3_128;
26	
27	/// Key width: xxh3_128 digest.
28	pub(crate) const VLLM_HASH_BYTES: usize = 16;
29	
30	/// Derives vLLM-compatible block-hash chains for one `(seed, block_size)`
31	/// configuration.
32	pub struct VllmBlockHasher {
33	    none_hash: [u8; VLLM_HASH_BYTES],
34	    block_size: usize,
35	}
36	
37	impl VllmBlockHasher {
38	    /// `python_hash_seed` must equal the `PYTHONHASHSEED` value set on every
39	    /// vLLM prefill process; `block_size` must equal vLLM's hash block size.
40	    pub fn new(python_hash_seed: &str, block_size: usize) -> Self {
41	        assert!(block_size > 0, "block_size must be positive");
42	        let mut seed_cbor = Vec::with_capacity(python_hash_seed.len() + 9);
43	        write_head(&mut seed_cbor, MAJOR_TSTR, python_hash_seed.len() as u64);
44	        seed_cbor.extend_from_slice(python_hash_seed.as_bytes());
45	        Self {
46	            none_hash: xxh3_128(&seed_cbor).to_be_bytes(),
47	            block_size,
48	        }
49	    }
50	
51	    /// Hash one block: `parent` is the previous block's hash (`None` for the
52	    /// first block, which chains off `NONE_HASH`).
53	    fn hash_block(
54	        &self,
55	        parent: Option<&[u8; VLLM_HASH_BYTES]>,
56	        token_ids: &[u32],
57	    ) -> [u8; VLLM_HASH_BYTES] {
58	        let parent = parent.unwrap_or(&self.none_hash);
59	        // array(3): [ bstr(parent), array(n)(uint...), null ]
60	        let mut buf = Vec::with_capacity(2 + VLLM_HASH_BYTES + 2 + 9 + 5 * token_ids.len());
61	        write_head(&mut buf, MAJOR_ARRAY, 3);
62	        write_head(&mut buf, MAJOR_BSTR, VLLM_HASH_BYTES as u64);
63	        buf.extend_from_slice(parent);
64	        write_head(&mut buf, MAJOR_ARRAY, token_ids.len() as u64);
65	        for &t in token_ids {
66	            write_head(&mut buf, MAJOR_UINT, u64::from(t));
67	        }
68	        buf.push(CBOR_NULL);
69	        xxh3_128(&buf).to_be_bytes()
70	    }
71	
72	    /// Key chain for a token sequence: one key per full block. vLLM never
73	    /// hashes the partial tail block; when the P/D tail extension lands it
74	    /// derives the extra key via [`Self::hash_block`] on the tail slice.
75	    pub fn key_chain(&self, token_ids: &[u32]) -> Vec<Vec<u8>> {
76	        let full = token_ids.len() / self.block_size;
77	        let mut keys = Vec::with_capacity(full);
78	        let mut parent: Option<[u8; VLLM_HASH_BYTES]> = None;
79	        for chunk in token_ids.chunks_exact(self.block_size) {
80	            let h = self.hash_block(parent.as_ref(), chunk);
81	            keys.push(h.to_vec());
82	            parent = Some(h);
83	        }
84	        keys
85	    }
86	
87	    /// The chain root (`xxh3_128(cbor(seed_string))`), for startup-time
88	    /// fingerprint logging: the P and D values must match byte-for-byte.
89	    pub fn none_hash(&self) -> [u8; VLLM_HASH_BYTES] {
90	        self.none_hash
91	    }
92	}
93	
94	const MAJOR_UINT: u8 = 0;
95	const MAJOR_BSTR: u8 = 2;
96	const MAJOR_TSTR: u8 = 3;
97	const MAJOR_ARRAY: u8 = 4;
98	const CBOR_NULL: u8 = 0xf6;
99	
100	/// Canonical (minimal-length) CBOR head: major type + unsigned argument.
101	fn write_head(out: &mut Vec<u8>, major: u8, value: u64) {
102	    let m = major << 5;
103	    match value {
104	        0..=23 => out.push(m | value as u8),
105	        24..=0xff => {
106	            out.push(m | 0x18);
107	            out.push(value as u8);
108	        }
109	        0x100..=0xffff => {
110	            out.push(m | 0x19);
111	            out.extend_from_slice(&(value as u16).to_be_bytes());
112	        }
113	        0x1_0000..=0xffff_ffff => {
114	            out.push(m | 0x1a);
115	            out.extend_from_slice(&(value as u32).to_be_bytes());
116	        }
117	        _ => {
118	            out.push(m | 0x1b);
119	            out.extend_from_slice(&value.to_be_bytes());
120	        }
121	    }
122	}
123	
124	#[cfg(test)]
125	mod tests {
126	    use super::*;
127	
128	    // Golden vectors captured from vLLM (pegaflow .venv, 2026-07-03):
129	    //   PYTHONHASHSEED=<seed> python -c "init_none_hash(xxhash_cbor); ..."
130	    // See docs/models/glm52/pd-vllm-prefill.md §3.
131	
132	    fn hex(bytes: &[u8]) -> String {
133	        use std::fmt::Write as _;
134	
135	        let mut encoded = String::with_capacity(bytes.len() * 2);
136	        for byte in bytes {
137	            write!(&mut encoded, "{byte:02x}").expect("writing to a String cannot fail");
138	        }
139	        encoded
140	    }
141	
142	    #[test]
143	    fn none_hash_matches_vllm() {
144	        assert_eq!(
145	            hex(&VllmBlockHasher::new("0", 4).none_hash),
146	            "1ebe36576dcb573f26b99533a20aaeca"
147	        );
148	        assert_eq!(
149	            hex(&VllmBlockHasher::new("42", 4).none_hash),
150	            "a9d2e63407fce1a26c9dc9d7fa2d7caf"
151	        );
152	    }
153	
154	    #[test]
155	    fn cbor_encoding_matches_cbor2_canonical() {
156	        // cbor2.dumps((NONE_HASH, (1,2,3,4), None), canonical=True)
157	        let h = VllmBlockHasher::new("0", 4);
158	        let mut buf = Vec::new();
159	        write_head(&mut buf, MAJOR_ARRAY, 3);
160	        write_head(&mut buf, MAJOR_BSTR, 16);
161	        buf.extend_from_slice(&h.none_hash);
162	        write_head(&mut buf, MAJOR_ARRAY, 4);
163	        for t in 1u64..=4 {
164	            write_head(&mut buf, MAJOR_UINT, t);
165	        }
166	        buf.push(CBOR_NULL);
167	        assert_eq!(
168	            hex(&buf),
169	            "83501ebe36576dcb573f26b99533a20aaeca8401020304f6"
170	        );
171	        // Multi-byte uint arguments (token id 100000 → 0x1a be32).
172	        let mut buf = Vec::new();
173	        write_head(&mut buf, MAJOR_ARRAY, 3);
174	        write_head(&mut buf, MAJOR_BSTR, 16);
175	        buf.extend_from_slice(&h.none_hash);
176	        write_head(&mut buf, MAJOR_ARRAY, 4);
177	        for t in 100_000u64..100_004 {
178	            write_head(&mut buf, MAJOR_UINT, t);
179	        }
180	        buf.push(CBOR_NULL);
181	        assert_eq!(
182	            hex(&buf),
183	            "83501ebe36576dcb573f26b99533a20aaeca841a000186a01a000186a11a000186a21a000186a3f6"
184	        );
185	    }
186	
187	    #[test]
188	    fn block_chain_matches_vllm() {
189	        let h = VllmBlockHasher::new("0", 4);
190	        let b1 = h.hash_block(None, &[1, 2, 3, 4]);
191	        let b2 = h.hash_block(Some(&b1), &[5, 6, 7, 8]);
192	        let tail = h.hash_block(Some(&b2), &[9, 10]);
193	        assert_eq!(hex(&b1), "0a8577df5ee3430515a8cc1f6e3ac52e");
